import {top,shell} from './screens.js';
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function photoHash(s){let h=2166136261;for(let i=0;i<s.length;i++)h=Math.imul(h^s.charCodeAt(i),16777619);return (h>>>0).toString(36);}
export function collectPhotos(records,petId){const items=[];for(const r of records.filter(r=>petId==='all'||r.petId===petId).sort((a,b)=>new Date(a.at)-new Date(b.at)||String(a.id).localeCompare(String(b.id)))){const counts=new Map();for(const src of r.photos||[]){if(typeof src!=='string'||!src.startsWith('data:image/'))continue;const hash=photoHash(src),n=counts.get(hash)||0;counts.set(hash,n+1);items.push({key:r.id+':'+hash+':'+n,src,record:r});}}return items;}
export function mergeAlbum(saved,items){const keys=new Set(items.map(x=>x.key)),slots={};for(const [key,slot] of Object.entries(saved?.slots||{}))if(keys.has(key)&&Number.isInteger(slot)&&slot>=0)slots[key]=slot;const occupied=new Set(Object.values(slots));for(const item of items)if(slots[item.key]===undefined){let slot=0;while(occupied.has(slot))slot++;slots[item.key]=slot;occupied.add(slot);}return {slots,seen:(saved?.seen||[]).filter(k=>keys.has(k))};}
let scope='',limit=24;let active=null;
function load(key,storage){try{return JSON.parse(storage.getItem(key))||{};}catch{return {};}}
function store(a){try{a.storage.setItem(a.key,JSON.stringify(a.layout));}catch{}}
export function renderAlbum(page,c){if(page!=='album')return null;const pid=c.state.current==='all'?'all':c.pet?.id;if(scope!==pid){scope=pid;limit=24;}const demo=new URLSearchParams(location.search).get('demo')==='1',storage=demo?sessionStorage:localStorage,key=(demo?'pomepet-demo-album:':'pomepet-album:')+pid,items=collectPhotos(c.state.records,pid),layout=mergeAlbum(load(key,storage),items);active={items,layout,key,storage};store(active);const visible=items.slice(-limit).sort((a,b)=>layout.slots[a.key]-layout.slots[b.key]);const baseRow=visible.length?Math.floor(Math.min(...visible.map(x=>layout.slots[x.key]))/4):0;let fresh=0;const html=visible.map((item,index)=>{const slot=layout.slots[item.key],col=slot%4,row=Math.floor(slot/4)-baseRow,seed=parseInt(photoHash(item.key),36),x=18+col*79+(seed%13)-6,y=22+row*61+(seed%15),angle=seed%35-17,unseen=!layout.seen.includes(item.key);return `<button class="album-photo ${unseen?'album-new':''}" data-album-photo="${E(item.key)}" aria-label="查看${E(item.record.activity)}照片，${E(new Date(item.record.at).toLocaleDateString('zh-CN'))}" style="left:${x}px;bottom:${y}px;--tilt:${angle}deg;--delay:${unseen?Math.min(fresh++,23)*.14:0}s;z-index:${index+1}"><img src="${E(item.src)}" alt="${E(item.record.activity)}的成长照片" loading="eager" draggable="false"></button>`;}).join('');const maxRow=Math.max(0,...visible.map(x=>Math.floor(layout.slots[x.key]/4)-baseRow)),height=Math.max(490,120+maxRow*61);return shell(top(c,'成长照片合集','profile')+`<div class="album-intro"><h2>${E(c.pet?.name||'我们的')}的回忆</h2><p>${items.length?'每个小日常，都落在这里。':'记下第一个小日常，装进我们的回忆。'}</p><small>${items.length} 张照片 · 点击照片，看看那一天</small></div><section class="album-pile ${items.length?'':'album-pile-empty'}" style="height:${height}px" aria-label="自由堆积的成长照片">${html||'<div class="album-empty"><span>♡</span><p>这里会慢慢装满<br>一起长大的日子</p><button data-add="profile">记录第一个小日常</button></div>'}</section>${items.length>limit?'<button id="albumMore" class="album-more">再看看更早的回忆</button>':''}<p class="album-footnote">照片自动收集自生活记录</p>`,'album');}
export function bindAlbum(api){const pile=document.querySelector('.album-pile');if(!pile||!active)return;const a=active;const mark=key=>{if(!a.layout.seen.includes(key)){a.layout.seen.push(key);store(a);}};pile.querySelectorAll('[data-album-photo]').forEach(button=>{const key=button.dataset.albumPhoto;if(matchMedia('(prefers-reduced-motion: reduce)').matches||!button.classList.contains('album-new'))mark(key);else button.addEventListener('animationend',()=>mark(key),{once:true});button.onclick=()=>openViewer(key,a,api);});document.querySelector('#albumMore')?.addEventListener('click',()=>{limit+=24;api.render();});}
function openViewer(key,a,api){const items=a.items;let index=items.findIndex(x=>x.key===key);if(index<0)return;document.querySelector('.album-overlay')?.remove();const previous=document.activeElement,overlay=document.createElement('div');overlay.className='album-overlay';overlay.innerHTML='<section class="album-viewer" role="dialog" aria-modal="true" aria-label="成长照片预览"><button class="album-close" aria-label="关闭照片">×</button><img class="album-full" alt=""><div class="album-photo-info"></div><div class="album-viewer-nav"><button aria-label="上一张照片">‹</button><span></span><button aria-label="下一张照片">›</button></div><button class="album-open-record">查看原记录</button></section>';document.body.append(overlay);const abort=new AbortController(),close=()=>{abort.abort();overlay.remove();previous?.focus();};const update=()=>{const item=items[index];overlay.querySelector('.album-full').src=item.src;overlay.querySelector('.album-full').alt=item.record.activity+'照片';overlay.querySelector('.album-photo-info').innerHTML='<strong>'+E(item.record.activity)+' · '+E(new Date(item.record.at).toLocaleDateString('zh-CN',{year:'numeric',month:'long',day:'numeric'}))+'</strong><p>'+E(item.record.note||'这个小日常，值得记住。')+'</p>';overlay.querySelector('.album-viewer-nav span').textContent=(index+1)+' / '+items.length;overlay.querySelector('[aria-label="上一张照片"]').disabled=index===0;overlay.querySelector('[aria-label="下一张照片"]').disabled=index===items.length-1;};overlay.querySelector('.album-close').onclick=close;overlay.onclick=e=>{if(e.target===overlay)close();};overlay.querySelector('[aria-label="上一张照片"]').onclick=()=>{index--;update();};overlay.querySelector('[aria-label="下一张照片"]').onclick=()=>{index++;update();};overlay.querySelector('.album-open-record').onclick=()=>{const id=items[index].record.id;close();api.openRecord(id);};document.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(e.key==='Tab'){const buttons=[...overlay.querySelectorAll('button:not(:disabled)')];if(e.shiftKey&&document.activeElement===buttons[0]){e.preventDefault();buttons.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===buttons.at(-1)){e.preventDefault();buttons[0].focus();}}},{signal:abort.signal});update();overlay.querySelector('.album-close').focus();}
